sites.find:
{
    y = 0;
    float *row_v_cursor = &grim_font2_uv_u[0].v;
    for (; y < 16; ++y) {
        float row_v = (float)y * 0.0625f;
        x = 0;
        float *entry_v = row_v_cursor;
        row_v_cursor += 32;
        for (; x < 16; entry_v += 2, ++x) {
            entry_v[-1] = (float)x * 0.0625f;
            entry_v[0] = row_v;
        }
    }
}

